import re
lines = open('outputs/grpo/train.log').read().splitlines()
step_re = re.compile(r'step:(\d+) - ')
seen = {}
for ln in lines:
    m = step_re.search(ln)
    if not m: continue
    step = int(m.group(1))
    if step in (1, 59, 72, 78, 84, 150, 300) and step not in seen:
        seen[step] = ln
for step in sorted(seen):
    ln = seen[step]
    for key in ['rollout_corr/']:
        for mm in re.finditer(r'(rollout_corr/[a-z_/]+):([^ ]+)', ln):
            print(step, mm.group(1), mm.group(2)[:14])
"

